output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper is obliged to collect the entrance cart before doing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_stand": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "collect_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_stand",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "collect_entrance_cart"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "Picking up shelf items is prohibited unless the shopper is currently pushing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        },
        "item_pickup_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "pushing_cart"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers are prohibited from carrying groceries by hand instead of using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "hands_free": {
          "not": "handFull"
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "pushing_cart"
              }
            ]
          },
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "must_return_cart_front",
    "text": "Before exiting, the shopper is obliged to return the cart to the front-left cart-return bay.",
    "abstraction": {
      "state_properties": {
        "at_front_return_bay": "at(0,1)",
        "cart_parked_front": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "return_cart_front": {
          "pre": {
            "and": [
              "at_front_return_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_front"
    }
  },
  {
    "id": "only_leave_cart_at_return_bay",
    "text": "Leaving the cart anywhere other than the front-left return bay is prohibited.",
    "abstraction": {
      "state_properties": {
        "at_front_return_bay": "at(0,1)",
        "away_from_front_return_bay": {
          "not": "at_front_return_bay"
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "leave_cart_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "pushing_cart",
              "away_from_front_return_bay"
            ]
          },
          "post": null
        },
        "leave_cart_in_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "pushing_cart",
              "at_front_return_bay"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Exiting the store while still pushing the cart is prohibited.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        },
        "cart_parked_front": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "cartless_exit": {
          "pre": {
            "and": [
              "EXIT",
              "cartless"
            ]
          },
          "post": null
        },
        "cart_exit": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_exit"
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "The shopper may exit only if the cart is already parked in the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_front": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        },
        "cart_not_parked_front": {
          "not": "cart_parked_front"
        }
      },
      "events": {
        "exit_without_returned_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_parked_front"
            ]
          },
          "post": null
        },
        "proper_exit": {
          "pre": {
            "and": [
              "EXIT",
              "cart_parked_front"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_without_returned_cart"
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart has been returned to the front bay, further item pickup is prohibited.",
    "abstraction": {
      "state_properties": {
        "cart_parked_front": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        },
        "post_return_cartless": "cart_parked_front"
      },
      "events": {
        "return_cart_front": {
          "pre": {
            "and": [
              "at(0,1)",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        },
        "pickup_after_cart_return": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "post_return_cartless"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_after_cart_return"
    }
  }
]
